#!/usr/bin/env python3
"""
Generate kexts/ArcAccel/arcaccel_stubs.h for Intel Arc IOAcceleratorFamily2 subclasses.
All class names use the Arc* prefix so ArcAccel.kext coexists cleanly with NullMoth's NVAccel.kext in AuxKC.
"""

from pathlib import Path

OUT_HEADER = Path(__file__).resolve().parent / "arcaccel_stubs.h"

CONTENT = """/*
 * GENERATED by gen_arc_stubs.py — IOAcceleratorFamily2 subclass definitions for ArcAccel.kext
 * All classes use Arc* names so ArcAccel.kext and NVAccel.kext never collide in AuxKC.
 *
 * SPDX-License-Identifier: PolyForm-Noncommercial-1.0.0
 * Required Notice: Copyright (c) 2026 NullMoth Systems (https://nullmothsystems.com)
 */

#pragma once

#include "iofam/IOAccelResource2.h"
#include "iofam/IOAccelSysMemory.h"
#include "iofam/IOAccelVidMemory.h"
#include "iofam/IOAccelLegacySurface.h"
#include "iofam/IOAccelLegacyDisplayPipe.h"
#include "iofam/IOAccelGLContext2.h"
#include "iofam/IOAccel2DContext2.h"
#include "iofam/IOAccelCLContext2.h"
#include "iofam/IOAccelVideoContext2.h"

class IOAccelDisplayPipeTransaction2;

/* 1. ArcResource (IOAccelResource2) */
class ArcResource : public IOAccelResource2 {
    OSDeclareDefaultStructors(ArcResource)
    ARC_TAHOE_FWD(ArcResource)
public:
    IODeviceMemory *fApDesc   = nullptr;
    unsigned        fApLogged = 0;

    void     rebuildPagingBuffer() APPLE_KEXT_OVERRIDE {}
    uint64_t getLevelOffset(unsigned char, unsigned char, int *err) APPLE_KEXT_OVERRIDE {
        if (err) *err = 0;
        return 0;
    }
    uint64_t getBackingLevelOffset(unsigned char, unsigned char, int *err) APPLE_KEXT_OVERRIDE {
        if (err) *err = 0;
        return 0;
    }
    uint64_t calculateIOSurfaceDeviceCacheVRAMBytes(unsigned long long *a, unsigned long long *b) APPLE_KEXT_OVERRIDE {
        if (a) *a = 0;
        if (b) *b = 0;
        return 0;
    }
    bool  addToAperture() APPLE_KEXT_OVERRIDE;
    void  removeFromAperture() APPLE_KEXT_OVERRIDE;
    void *getApertureMemoryDescriptor(unsigned long long *offsetOut) APPLE_KEXT_OVERRIDE;
    void  free() APPLE_KEXT_OVERRIDE;
};
OSDefineMetaClassAndStructors(ArcResource, IOAccelResource2)

/* 2. ArcSysMemory (IOAccelSysMemory) */
class ArcSysMemory : public IOAccelSysMemory {
    OSDeclareDefaultStructors(ArcSysMemory)
    ARC_TAHOE_FWD(ArcSysMemory)
};
OSDefineMetaClassAndStructors(ArcSysMemory, IOAccelSysMemory)

/* 3. ArcVidMemory (IOAccelVidMemory — backed by UMA System RAM on Intel Arc iGPU) */
class ArcVidMemory : public IOAccelVidMemory {
    OSDeclareDefaultStructors(ArcVidMemory)
    ARC_TAHOE_FWD(ArcVidMemory)
public:
    IOBufferMemoryDescriptor *fUmaBuf  = nullptr;
    void                     *fKva     = nullptr;
    unsigned long long        fPhys    = 0;
    unsigned long long        fBytes   = 0;
    bool                      fScanout = false;

    uint64_t getPhysicalSegment(unsigned long long offset, unsigned long long *lengthOut) APPLE_KEXT_OVERRIDE;
    bool     allocPhysical() APPLE_KEXT_OVERRIDE;
    void     deallocPhysical() APPLE_KEXT_OVERRIDE;
    void     free() APPLE_KEXT_OVERRIDE;
};
OSDefineMetaClassAndStructors(ArcVidMemory, IOAccelVidMemory)

/* 4. ArcSurface (IOAccelLegacySurface) */
class ArcSurface : public IOAccelLegacySurface {
    OSDeclareDefaultStructors(ArcSurface)
    ARC_TAHOE_FWD(ArcSurface)
public:
    bool copyFromBuffer(int, int, int, int, unsigned int, unsigned int,
                        IOAccelEvent *, IOAccelResource2 *, IOAccelSysMemory *,
                        unsigned int, unsigned long long, unsigned int) APPLE_KEXT_OVERRIDE {
        return true;
    }
    bool copyToBuffer(int, int, int, int, unsigned int, unsigned int,
                      IOAccelEvent *, IOAccelResource2 *, IOAccelSysMemory *,
                      unsigned int, unsigned long long, unsigned int) APPLE_KEXT_OVERRIDE {
        return true;
    }
    void submitSwapCopy(IOAccelEvent *, IOAccelResource2 *, IOAccelResource2 *) APPLE_KEXT_OVERRIDE {}
    void shapeSurface(unsigned int, unsigned short, unsigned short) APPLE_KEXT_OVERRIDE {}
    uint32_t getDirtyBufferBitsFromPrivateModeBits(unsigned long long) APPLE_KEXT_OVERRIDE { return 0; }
    void setSyncCommand(unsigned int *, unsigned int &, unsigned int &,
                        _AMDSurfaceSwapSyncOptions const &) const APPLE_KEXT_OVERRIDE {}
    void _pure335() APPLE_KEXT_OVERRIDE {}
};
OSDefineMetaClassAndStructors(ArcSurface, IOAccelLegacySurface)

/* 5. ArcDisplayPipe (IOAccelLegacyDisplayPipe) */
struct ArcIopSrc {
    IOMemoryDescriptor *md  = nullptr;
    IOMemoryMap        *map = nullptr;
    unsigned            id  = 0;
};

class ArcDisplayPipe : public IOAccelLegacyDisplayPipe {
    OSDeclareDefaultStructors(ArcDisplayPipe)
    ARC_TAHOE_FWD(ArcDisplayPipe)
public:
    static constexpr unsigned kIopSrcSlots = 8;
    ArcIopSrc fIopSrc[kIopSrcSlots] = {};
    unsigned  fIopNext              = 0;

    void        iopDropSources();
    const void *iopMapSurface(unsigned id, IOMemoryDescriptor *md, unsigned long long need);

    IOAccelMemory *initFramebufferResource(unsigned int index, IOAccelResource2 *res) APPLE_KEXT_OVERRIDE;
    IOReturn       validateTransaction(IOAccelDisplayPipeTransaction2 *txn) APPLE_KEXT_OVERRIDE;
    IOReturn       performTransaction(IOAccelDisplayPipeTransaction2 *txn) APPLE_KEXT_OVERRIDE;
    bool           isTransactionComplete(IOAccelDisplayPipeTransaction2 *txn) APPLE_KEXT_OVERRIDE;
    void           enableVBLInterrupt() APPLE_KEXT_OVERRIDE {}
    void           disableVBLInterrupt() APPLE_KEXT_OVERRIDE {}
    void           enableTransactionInterrupt() APPLE_KEXT_OVERRIDE {}
    void           disableTransactionInterrupt() APPLE_KEXT_OVERRIDE {}
    bool           isCurrentModeAcceleratorBacked() APPLE_KEXT_OVERRIDE { return true; }
    void           free() APPLE_KEXT_OVERRIDE;
};
OSDefineMetaClassAndStructors(ArcDisplayPipe, IOAccelLegacyDisplayPipe)

/* 6. Legacy GL / 2D / CL / Video Context Stubs (All rendering goes through Metal 3 -> ArcMTLDriver.bundle) */
class ArcGLContext : public IOAccelGLContext2 {
    OSDeclareDefaultStructors(ArcGLContext)
    ARC_TAHOE_FWD(ArcGLContext)
public:
    void _pure362() APPLE_KEXT_OVERRIDE {}
    void _pure363() APPLE_KEXT_OVERRIDE {}
    void _pure364() APPLE_KEXT_OVERRIDE {}
    void _pure367() APPLE_KEXT_OVERRIDE {}
};
OSDefineMetaClassAndStructors(ArcGLContext, IOAccelGLContext2)

class Arc2DContext : public IOAccel2DContext2 {
    OSDeclareDefaultStructors(Arc2DContext)
    ARC_TAHOE_FWD(Arc2DContext)
public:
    void _pure362() APPLE_KEXT_OVERRIDE {}
    void _pure363() APPLE_KEXT_OVERRIDE {}
};
OSDefineMetaClassAndStructors(Arc2DContext, IOAccel2DContext2)

class ArcCLContext : public IOAccelCLContext2 {
    OSDeclareDefaultStructors(ArcCLContext)
    ARC_TAHOE_FWD(ArcCLContext)
};
OSDefineMetaClassAndStructors(ArcCLContext, IOAccelCLContext2)

class ArcVideoContext : public IOAccelVideoContext2 {
    OSDeclareDefaultStructors(ArcVideoContext)
    ARC_TAHOE_FWD(ArcVideoContext)
};
OSDefineMetaClassAndStructors(ArcVideoContext, IOAccelVideoContext2)
"""

def main() -> None:
    OUT_HEADER.write_text(CONTENT, encoding="utf-8")
    print(f"Generated {OUT_HEADER} ({len(CONTENT)} bytes)")

if __name__ == "__main__":
    main()
